// axe-core mini stub - provides basic accessibility checks if CDN unavailable
(function() {
    window.axe = {
        run: function(options, callback) {
            var violations = [];
            
            // Check 1: Images without alt text
            var images = document.querySelectorAll('img:not([alt])');
            if (images.length > 0) {
                violations.push({
                    id: 'image-alt',
                    impact: 'critical',
                    description: 'Images must have alternate text',
                    help: 'Elements must have an alt attribute',
                    helpUrl: 'https://dequeuniversity.com/rules/axe/4.8/image-alt',
                    nodes: Array.from(images).map(function(img) { return { target: [img.tagName.toLowerCase()] }; })
                });
            }
            
            // Check 2: Form controls without labels
            var inputs = document.querySelectorAll('input:not([type="hidden"]):not([type="submit"]):not([type="button"]):not([aria-label]):not([aria-labelledby])');
            var unlabeledInputs = Array.from(inputs).filter(function(input) {
                return !input.id || !document.querySelector('label[for="' + input.id + '"]');
            });
            if (unlabeledInputs.length > 0) {
                violations.push({
                    id: 'label',
                    impact: 'critical',
                    description: 'Form elements must have labels',
                    help: 'Every form element must have a label',
                    helpUrl: 'https://dequeuniversity.com/rules/axe/4.8/label',
                    nodes: unlabeledInputs.map(function(input) { return { target: [input.tagName.toLowerCase()] }; })
                });
            }
            
            // Check 3: Buttons without accessible names
            var buttons = document.querySelectorAll('button:empty:not([aria-label]):not([aria-labelledby])');
            if (buttons.length > 0) {
                violations.push({
                    id: 'button-name',
                    impact: 'critical',
                    description: 'Buttons must have discernible text',
                    help: 'Buttons must have accessible text',
                    helpUrl: 'https://dequeuniversity.com/rules/axe/4.8/button-name',
                    nodes: Array.from(buttons).map(function(btn) { return { target: ['button'] }; })
                });
            }
            
            callback(null, { violations: violations });
        }
    };
})();
